const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      notification: prepared.notification,
      source_result: prepared.source_result,
      payload: prepared.payload,
      metadata: prepared.metadata,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];

const input = $input.first().json || {};

function fail({ code, message, details = [], inputSnapshot = {} }) {
  return [
    {
      json: {
        stop_before_send: true,
        success: false,
        component_id: "C2-I1",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        notification: {
          channel: "email",
          status: "failed",
          to: input.config?.to || null,
          subject: null,
          provider_message_id: null
        },
        source_result: {
          component_id: input.input?.component_id || null,
          destination: input.input?.destination || null,
          write: input.input?.write || null
        },
        payload: input.input?.payload || {},
        metadata: input.input?.metadata || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log",
        input_snapshot: inputSnapshot
      }
    }
  ];
}

function renderTemplate(template, values) {
  return String(template || "").replace(/\{\{(.*?)\}\}/g, (_, key) => {
    const cleanKey = key.trim();
    return values[cleanKey] ?? "";
  });
}

function safe(value) {
  return value === undefined || value === null || value === "" ? "-" : String(value);
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty.",
    inputSnapshot: input
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object.",
    inputSnapshot: input
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-I1 will not send success notification when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ],
    inputSnapshot: input
  });
}

if (source.next_action !== "notify_team") {
  return fail({
    code: "NOTIFICATION_NOT_REQUESTED",
    message: "source.next_action is not notify_team.",
    details: [{ next_action: source.next_action || null }],
    inputSnapshot: input
  });
}

if (!config.to) {
  return fail({
    code: "MISSING_RECIPIENT",
    message: "config.to is required.",
    inputSnapshot: input
  });
}

if (!config.from) {
  return fail({
    code: "MISSING_FROM_EMAIL",
    message: "config.from is required.",
    inputSnapshot: input
  });
}

if (config.channel && config.channel !== "email") {
  return fail({
    code: "UNSUPPORTED_CHANNEL",
    message: "C2-I1 v1 only supports email notifications.",
    details: [{ channel: config.channel }],
    inputSnapshot: input
  });
}

const subject = renderTemplate(
  config.subject_template || "New {{event_type}} automation event",
  {
    event_type: source.event_type || "",
    event_id: source.event_id || "",
    destination_type: source.destination?.type || ""
  }
);

const payload = source.payload || {};
const destination = source.destination || {};
const write = source.write || {};
const metadata = source.metadata || {};

const textBody = [
  `Automation notification`,
  ``,
  `Event ID: ${safe(source.event_id)}`,
  `Event Type: ${safe(source.event_type)}`,
  `Source Component: ${safe(source.component_id)}`,
  `Destination: ${safe(destination.type)}`,
  `Record ID: ${safe(destination.record_id)}`,
  `Write Status: ${safe(write.status)}`,
  ``,
  `Payload`,
  `Name: ${safe(payload.name || [payload.firstname, payload.lastname].filter(Boolean).join(" "))}`,
  `Email: ${safe(payload.email)}`,
  `Company: ${safe(payload.company)}`,
  `Message: ${safe(payload.message)}`,
  ``,
  `Metadata`,
  `Origin: ${safe(metadata.origin)}`,
  `Environment: ${safe(metadata.environment)}`,
  ``,
  `Next Action: ${safe(config.default_next_action || "end")}`
].join("\n");

return [
  {
    json: {
      stop_before_send: false,
      email: {
        from: config.from,
        to: config.to,
        subject,
        text: textBody
      },
      context: {
        component_id: "C2-I1",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        notification: {
          channel: "email",
          status: "prepared",
          to: config.to,
          subject,
          provider_message_id: null
        },
        source_result: {
          component_id: source.component_id || null,
          destination: source.destination || null,
          write: source.write || null
        },
        payload: source.payload || {},
        metadata: source.metadata || {},
        next_action: config.default_next_action || "end"
      }
    }
  }
];

const emailOutput = $input.first().json || {};
const prepared = $("Prepare Email Notification").first().json;
const context = prepared.context;

const providerMessageId =
  emailOutput.messageId ||
  emailOutput.message_id ||
  emailOutput.id ||
  null;

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      notification: {
        ...context.notification,
        status: "sent",
        provider_message_id: providerMessageId
      },
      source_result: context.source_result,
      payload: context.payload,
      metadata: context.metadata,
      error: null,
      next_action: context.next_action
    }
  }
];
